using System.Collections.Frozen;
using Companion.Contracts;
using Companion.Contracts.Vision;

namespace Companion.Perception.Internal;

/// <summary>Where a built-in glyph was cut (provenance; the Perception tests re-cut every glyph and compare).</summary>
/// <param name="Font">Font style.</param>
/// <param name="Char">Character.</param>
/// <param name="Capture">Full-scale client capture (a byte-identical copy in tests\TestData\images, from proofs\out).</param>
/// <param name="Region">Client rect of the text crop.</param>
/// <param name="Text">Text of the crop (non-space characters = glyphs, left to right).</param>
/// <param name="Index">Index of the glyph in <paramref name="Text"/> (spaces skipped).</param>
/// <param name="Borrowed">
/// The glyph was NOT cut from text the font reads but from another text of the game (another size, weight or colour)
/// because no capture shows the character in that font yet. A borrowed glyph still matches its character, but less
/// tightly than a real one; it is deleted as soon as a real instance of the character exists.
/// </param>
/// <param name="FromTile">
/// (2026-10-15) <paramref name="Region"/> is a Stock-tab tile box and the glyph is cut from the clean image of its count
/// (<see cref="IconGrid.FindCount"/>: the glyphs without the icon behind them), not from a raw crop of the region.
/// </param>
internal sealed record GlyphSource(string Font, char Char, string Capture, RectI Region, string Text, int Index, bool Borrowed = false, bool FromTile = false);

/// <summary>One glyph image of a font (a font holds several instances of a character: subpixel phase).</summary>
/// <param name="Char">Character.</param>
/// <param name="Image">Glyph image (ink 0 on 255, with a margin).</param>
internal sealed record FontGlyph(char Char, GrayImage Image);

/// <summary>
/// Digit fonts compiled into the build (no file reads in this assembly), cut at FULL scale from the Make-tab captures
/// of 2026-10-14/15 (tests\TestData\images: live_ability_make_full.png and make_fav1..5_full.png, favourites 1-5
/// selected; live_ability_view_full.png, the phase announcement). Glyphs are stored as ink masks ('#' ink, '.'
/// background, rows joined by '|') produced by <see cref="GlyphCutter"/>; the provenance test re-cuts them from the
/// captures. Every character has up to four REAL instances cut at different places (the same glyph renders 1 px wider
/// or taller depending on its subpixel position and then scores only 0.64-0.90 against itself), so a fresh glyph
/// matches its nearest instance:
/// <list type="bullet">
/// <item><c>parchment-pair</c>: the Materials Required owned/required pairs (green, or red when short, medium weight,
/// ~18 px). Real: 0 1 3 4 5 6 7 9 / from the pairs of the six captures. Borrowed: 2 8 from the green numbers of the
/// recipe descriptions ("+(1451-2418)", "8160": same size and colour, slightly wider; no pair shows a 2 or an 8 yet).
/// Also used by the "Requires" line (no capture shows that line).</item>
/// <item><c>badge-dark</c>: the product's owned-count badge (dark brown bold digits on white, ~21 px). Real: 0 1 2 5
/// 6 from the badges "0", "1", "11", "25", "26". Borrowed: 3 4 8 9 from the bold reputation stats ("96692", "96499",
/// "804", "963": same weight and size, 0.83-0.97 against the badge's own 0 2 6), 7 from "47" of the announcement.</item>
/// <item><c>counter-dark</c>: the small 'a/b' counter in the bar under the product picture (dark brown, ~19 px; the
/// text overlaps the bar's outline, which is lighter and falls outside the ink). Real: 0 3 5 6 / from "0/300",
/// "5/300", "6/300". Borrowed: 1 4 7 9 from the pairs (0.82-0.97 against the counter's own glyphs), 2 8 from the
/// descriptions.</item>
/// <item><c>stock-count-dark</c> (2026-10-15): the counts of the Ability view's Stock tab (dark brown digits with a white
/// halo at each tile's bottom right; 18-20 px tall up to 3 digits, 15-16 px for 4-5 digits), cut from the clean count
/// images of tiles of the stock_*_full.png captures (<see cref="GlyphSource.FromTile"/>). Real: every digit, a small
/// (4-5 digit) instance of 0 1 2 3 4 5 8 9 among them.</item>
/// </list>
/// Reads that contain a borrowed glyph normally need OCR agreement (the digits-only rule needs strong glyphs).
/// </summary>
internal static class BuiltInDigitFonts
{
