    private static readonly Lazy<IReadOnlyDictionary<string, IReadOnlyList<FontGlyph>>> FontsLazy =
        new(Build, LazyThreadSafetyMode.ExecutionAndPublication);

    /// <summary>Font style → glyph instances (several per character).</summary>
    public static IReadOnlyDictionary<string, IReadOnlyList<FontGlyph>> Fonts => FontsLazy.Value;

    /// <summary>The embedded masks by (font, char), in <see cref="Sources"/> order.</summary>
    internal static IReadOnlyList<(string Font, char Char, string Mask)> Masks => Data;

    private static IReadOnlyDictionary<string, IReadOnlyList<FontGlyph>> Build() =>
        Data.GroupBy(d => d.Font, StringComparer.Ordinal)
            .ToFrozenDictionary(
                g => g.Key,
                g => (IReadOnlyList<FontGlyph>)[.. g.Select(d => new FontGlyph(d.Char, GlyphCutter.ToImage(d.Mask)))],
                StringComparer.Ordinal);

